// Signs a JSON body for Convex: HMAC-SHA256 over "<timestamp>.<body>".
const crypto = require('crypto');
function signed(payload) {
  const body = JSON.stringify(payload);
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = 'sha256=' + crypto
    .createHmac('sha256', $env.LENDLOOP_SECRET_TO_CONVEX)
    .update(timestamp + '.' + body)
    .digest('hex');
  return { body, timestamp, signature };
}
// Runs when another LendLoop workflow fails (after its retries).
// Logs the failure and reports it to Convex so admins see it in the app.
const e = $input.first().json;
const report = {
  workflow: (e.workflow && e.workflow.name) || 'unknown workflow',
  node: e.execution && e.execution.lastNodeExecuted,
  message: (e.execution && e.execution.error && e.execution.error.message) || 'unknown error',
  executionId: e.execution && e.execution.id ? String(e.execution.id) : undefined,
};
console.error('[LendLoop error]', JSON.stringify(report));
return [{ json: signed(report) }];
